def run():
    t0 = time.time()
    print("=" * 74)
    print('v960 -- PRIME.PORT.COUPLEDTAU.SURFACE_CLOSURE.01 (rounds 260/262/263/')
    print('268/269/270/271 + typed measurements 272/273/275): the terminal-surface')
